import rdflib
g = rdflib.Graph(); g.parse('/app/university_graph.ttl', format='turtle')
base = open('/app/solution.sparql').read()
# Variant: count per course (class) instead of per department
q = base.replace("""    SELECT ?crowdedDepartment
    WHERE {
      ?course uni:isTaughtIn ?crowdedDepartment .""",
"""    SELECT ?crowdedDepartment
    WHERE {
      ?course uni:isTaughtIn ?crowdedDepartment .""")
q2 = base.replace("""      ?course uni:isTaughtIn ?crowdedDepartment .
      ?student uni:isEnrolledIn ?course ;""",
"""      ?course uni:isTaughtIn ?crowdedDepartment .
      ?student uni:isEnrolledIn ?course ;""")
for name, q in [("per-department", base)]:
    print(name, sorted(tuple(str(x) for x in r) for r in g.query(q)))

# per-class variant built by grouping on course
per_class = """
PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?professorName (GROUP_CONCAT(DISTINCT ?country; separator=", ") AS ?countries) WHERE {
  { SELECT ?professor ?professorName ?country WHERE {
      ?professor uni:hasName ?professorName ; uni:worksIn ?d .
      ?d uni:belongsTo ?u . ?u uni:locatedInCountry ?country .
    } ORDER BY ?professorName ?country }
  ?professor uni:role ?role . FILTER(REGEX(STR(?role), "^Professor( |$)"))
  ?professor uni:worksIn ?dep .
  ?dep uni:belongsTo ?euU . ?euU uni:locatedInCountry ?euC .
  VALUES ?euC { "GR" "PT" "FR" "DE" "ES" }
  ?professor uni:worksIn ?dep2 . ?course uni:isTaughtIn ?dep2 .
  { SELECT ?dep2 WHERE {
      ?c uni:isTaughtIn ?dep2 . ?s uni:isEnrolledIn ?c ; uni:hasEnrollmentDate ?ed .
      FILTER(?ed <= "2025-08-16"^^xsd:date)
      FILTER NOT EXISTS { ?s uni:hasGraduationDate ?gd . FILTER(?gd <= "2025-08-16"^^xsd:date) }
    } GROUP BY ?dep2 HAVING (COUNT(DISTINCT ?s) > 10) }
} GROUP BY ?professorName ORDER BY ?professorName
"""
print("(per-class grouping is same construct here)")
# actual per-class counts
TODAY=rdflib.Literal("2025-08-16", datatype=rdflib.XSD.date)
U=rdflib.Namespace("http://university.org/ontology/")
from collections import defaultdict
c=defaultdict(set)
for s in set(g.subjects(U.isEnrolledIn,None)):
    grad=[x.toPython() for x in g.objects(s,U.hasGraduationDate)]
    if any(x<=TODAY.toPython() for x in grad): continue
    for cr in g.objects(s,U.isEnrolledIn):
        c[cr].add(s)
for cr,n in sorted(c.items(), key=lambda kv:str(kv[0])):
    print(" class", str(cr).split('/')[-1], len(n), ">10" if len(n)>10 else "")
